//! `rip-datagen`: self-play training data for the NNUE trainer, generated by the engine with its
//! embedded network (Matt-Magie step 102, stage A).
//!
//! - `generator`: one thread's games, the data format and the recording rules;
//! - `config`: the configuration file `rip-datagen.toml`;
//! - `seeds`: the base seed of a run and the seeds of its threads;
//! - `runner`: a run - threads, the batch directory, `batch.log` and `MANIFEST.json`;
//! - `log` and `manifest`: the two records a run leaves next to its data;
//! - `stats` and `pager`: `rip-datagen stats` over every batch of a data directory.

pub mod config;
pub mod generator;
pub mod log;
pub mod manifest;
pub mod pager;
pub mod runner;
pub mod seeds;
pub mod stats;

/// Version of the data generator. Raise it whenever the same configuration and seed produce
/// different data (the games, the recording rules or the format), so every batch names the
/// generator that made it; the engine version alone does not say that.
pub const DATAGEN_VERSION: &str = "1.0.0";

/// Commit the binary was built from (`build.rs`), or `unknown` outside a git checkout.
pub fn engine_commit() -> &'static str {
    option_env!("RIP_GIT_COMMIT").unwrap_or("unknown")
}

/// Version of the engine whose search and network generate the data.
pub fn engine_version() -> &'static str {
    env!("CARGO_PKG_VERSION")
}

/// Name and fingerprint of the embedded network, the only one `rip-datagen` uses.
pub fn net() -> (&'static str, u32) {
    crate::nnue_service::embedded_net()
}

/// Text of `rip-datagen version`.
pub fn version_text() -> String {
    let (name, fnv) = net();
    format!(
        "rip-datagen {DATAGEN_VERSION}\n\
         engine      {} (commit {})\n\
         net         {name} (embedded, fnv {fnv:08x})\n\
         target      {}-{}\n",
        engine_version(),
        engine_commit(),
        std::env::consts::ARCH,
        std::env::consts::OS,
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_version_names_generator_engine_and_net() {
        let text = version_text();
        assert!(text.starts_with(&format!("rip-datagen {DATAGEN_VERSION}\n")));
        assert!(text.contains(engine_version()));
        let (name, fnv) = net();
        assert!(!name.is_empty());
        assert!(text.contains(&format!("{name} (embedded, fnv {fnv:08x})")));
    }
}
